def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = [[0] * n for _ in range(n)]

    # Initialize the first row and column
    for i in range(n):
        dp[0][i] = matrix[0][i]
        dp[i][0] = matrix[i][0]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    # Calculate the maximum average
    max_avg = float('-inf')
    for i in range(n):
        for j in range(n):
            max_avg = max(max_avg, dp[i][j] / (i+1)*(j+1))

    return max_avg
```

